    sh_state.last_q_bi.y == 0.0 && sh_state.last_q_bi.z == 0.0) {
    sh_state.last_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
}

// 1. Check Configuration Validity
if ((sh_input.enable != 0 && sh_input.enable != 1) ||
    (sh_input.valid != 0 && sh_input.valid != 1) ||
    (sh_config.max_hold_cycles < 1) || (sh_config.max_hold_cycles > 20)) {
    sh_output.mode = SH_FAULT;
    sh_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    sh_output.relative_step_rad = 0.0;
    sh_state.mode = SH_FAULT;
    return;
}

// 2. Handle Disabled State
if (sh_input.enable == 0) {
    sh_output.mode = SH_OFF;
    sh_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    sh_output.relative_step_rad = 0.0;
    sh_state.dropouts = 0;
    sh_state.last_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    sh_state.mode = SH_OFF;
    return;
