    status = adcs_quat_normalize(sh_input.q_bi, &norm_q);
    if (status == ADCS_OK) {
        dot_product = norm_q.w * sh_state.last_q_bi.w +
                      norm_q.x * sh_state.last_q_bi.x +
                      norm_q.y * sh_state.last_q_bi.y +
                      norm_q.z * sh_state.last_q_bi.z;

