    sh_state.last_q_bi = aligned_q;
    sh_output.q_bi = aligned_q;
    sh_output.relative_step_rad = rel_step;
    sh_state.mode = SH_TRACK;
} else {
    sh_state.dropouts++;

    if (sh_state.dropouts > sh_config.max_hold_cycles) {
        sh_output.mode = SH_FAULT;
        sh_output.q_bi = sh_state.last_q_bi;
        sh_output.relative_step_rad = 0.0;
        sh_state.mode = SH_FAULT;
